style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
/* Global page styling */
    body, html {
        background-color: #ffffff !important; /* pure white */
        color: #ffb6c1 !important; /* light pink aesthetic */
        font-family: Arial, sans-serif !important; /* normal clean font */
        margin: 0 !important;
        padding: 0 !important;
    }

    /* Make all text light pink */
    * {
        color: #ffb6c1 !important;
    }

    /* Light pink aesthetic buttons */
    button,
    .btn-common,
    .btn-primary,
    .btn-secondary,
    .btn-control,
    .btn-growth-lg,
    .btn-growth-md,
    .btn-growth-sm,
    .btn-fixed-width,
    .btn-cta-lg,
    .btn-cta-md,
    .btn-cta-sm {
        background-color: #ffb6c1 !important; /* light pink */
        color: #ffffff !important; /* white text */
        border: none !important;
        padding: 10px 18px !important;
        border-radius: 6px !important;
        font-size: 16px !important;
        cursor: pointer !important;
        transition: 0.2s ease !important;
    }

    /* Hover effect */
    button:hover,
    .btn-common:hover,
    .btn-primary:hover,
    .btn-secondary:hover,
    .btn-control:hover,
    .btn-growth-lg:hover,
    .btn-growth-md:hover,
    .btn-growth-sm:hover,
    .btn-fixed-width:hover,
    .btn-cta-lg:hover,
    .btn-cta-md:hover,
    .btn-cta-sm:hover {
        background-color: #ff9bb0 !important; /* slightly deeper pink */
    }

    /* Remove Roblox grey backgrounds */
    .content,
    .container,
    .section,
    .game-card,
    .thumbnail-2d-container,
    .thumbnail-3d-container,
    .profile-header,
    .header,
    .footer,
    .rbx-navbar,
    .rbx-tabs,
    .rbx-tab,
    .rbx-tab-active {
        background-color: #ffffff !important;
    }

    /* Make borders match the aesthetic */
    * {
        border-color: #ffb6c1 !important;
    }
}
